fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We know `v` is nonempty and sorted in nondecreasing order,
    // and that `k` appears at least once in `v`.

    // We'll do a lower‐bound style binary search:
    // find the first index `i` such that `v[i] >= k`.
    // Because `k` is in the array, that index will satisfy `v[i] == k`.

    let mut lo: usize = 0;
    let mut hi: usize = v.len(); // note: hi is one past the last valid index

    while lo < hi {
        // avoid overflow: mid in [lo, hi)
        let mid = lo + (hi - lo) / 2;
        if v[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // At this point lo == hi, and it's the first index where v[lo] >= k.
    // Since k is guaranteed to appear, v[lo] == k and lo < v.len().
    lo
}

